import{_ as a}from"./chunks/Audio.COine8Wh.js";import{_ as r}from"./chunks/Tags.BJ536pW3.js";import{c as o,o as n,j as t,G as i,ae as s,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const p=JSON.parse('{"title":"Laken Riley Act","description":"","frontmatter":{"legisId":"2025-01-29-laken-riley-act","title":"Laken Riley Act","displayTitle":"Laken Riley Act","lawNumber":"119-1","billNumber":"S. 5","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ1.xml","publishDate":"2025-01-29T00:00:00-05:00","industries":["immigration","law-enforcement","government-operations"],"agencies":["Department of Homeland Security"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Laken Riley Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-01-29-laken-riley-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Laken Riley Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-01-29-laken-riley-act\\",\\"datePublished\\":\\"2025-01-29T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-01-29-laken-riley-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-01-29-laken-riley-act.md","filePath":"congress-bills/2025-01-29-laken-riley-act.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2025-01-29-laken-riley-act.md"},g=Object.assign(d,{setup(c){return(m,e)=>(n(),o("div",null,[e[0]||(e[0]=t("h1",{id:"laken-riley-act",tabindex:"-1"},[l("Laken Riley Act "),t("a",{class:"header-anchor",href:"#laken-riley-act","aria-label":'Permalink to "Laken Riley Act"'},"​")],-1)),i(a),i(r,{list:"/congress-bills"}),e[1]||(e[1]=s('<p>Signed into law on Wednesday, January 29, 2025. Public Law 119-1, S. 5.</p><p><strong>Headline:</strong> The Laken Riley Act mandates detention of certain inadmissible noncitizens accused of theft-related or violent crimes.</p><p><strong>Why it matters:</strong> The law expands mandatory immigration detention and gives states a faster path to challenge federal enforcement of detention, removal, visa, and parole rules.</p><p><strong>What the law does:</strong></p><ul><li>Requires the Department of Homeland Security to issue detainers and promptly take custody of covered noncitizens not already held by authorities.</li><li>Covers certain inadmissible noncitizens charged with, arrested for, convicted of, or admitting conduct involving specified theft offenses, assault of a law enforcement officer, or crimes causing death or serious bodily injury.</li><li>Uses the law of the jurisdiction where the conduct occurred to define covered offenses and serious bodily injury.</li><li>Allows authorized state officials to sue federal officials over alleged violations of specified immigration detention, removal, bond, visa, and parole requirements.</li><li>Directs federal courts to expedite qualifying state lawsuits and permits court orders requiring compliance.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Certain inadmissible noncitizens accused of specified theft-related or violent conduct.</li><li>State attorneys general and other authorized state officers claiming harm to their states or residents.</li><li>Federal immigration officials responsible for detention, removal, visas, bonds, and parole.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>A covered noncitizen may face prompt federal detention based on an arrest, charge, conviction, or admission involving a listed offense.</li><li>State residents may be cited as harmed when their state seeks federal court enforcement, including for financial harm exceeding $100.</li></ul><p><strong>Context:</strong> States may pursue these cases on an expedited basis when they or their residents meet the law’s harm threshold.</p><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="laken-riley-act-1" tabindex="-1">Laken Riley Act <a class="header-anchor" href="#laken-riley-act-1" aria-label="Permalink to &quot;Laken Riley Act&quot;">​</a></h3><p>The Laken Riley Act requires federal immigration authorities to detain certain inadmissible noncitizens who are accused of specified theft-related or violent crimes. It also allows states claiming harm to seek expedited court orders enforcing several federal immigration detention, removal, visa, and parole requirements.</p><p><strong>Key takeaways:</strong></p><ul><li>The Department of Homeland Security must issue a detainer and promptly take custody of covered noncitizens who are not already held by federal, state, or local authorities.</li><li>The detention requirement covers certain inadmissible noncitizens who are charged with, arrested for, convicted of, or admit conduct involving burglary, theft, larceny, shoplifting, assault of a law enforcement officer, or a crime causing death or serious bodily injury.</li><li>The listed offenses and serious bodily injury are defined under the law of the jurisdiction where the conduct occurred.</li><li>State attorneys general and other authorized state officers may sue federal officials for alleged violations involving immigration detention and removal, release on bond or parole, visa restrictions, and limits on immigration parole.</li><li>A state or its residents qualify as harmed for these lawsuits if they experience harm, including financial harm exceeding $100.</li><li>Federal courts must expedite these state enforcement lawsuits to the greatest extent practicable and may issue appropriate court orders requiring compliance.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ1.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ1.xml</a></p>',16))]))}});export{p as __pageData,g as default};
